/**
 * The migrate process: applies the migration history (drizzle/, generated by drizzle-kit and reviewed, plus hand-written
 * SQL for triggers, grants and policies) as the owner role, itrms_owner. The Compose `migrate` service runs it before the
 * API starts; it exits 0 when the database is current. It then installs the request-context key (CONTEXT_HMAC_KEY) where
 * the database verifies the API's signed context (ADR-0048): the key is never in git or in a migration.
 */
import { join } from 'node:path';

import { drizzle } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import { contextKeyId, contextKeyOf } from '@itrms/kernel/db';
import { Pool } from 'pg';

import { fail, start } from './start';

/** Next to the bundle: dist/../drizzle (the image ships both). */
const MIGRATIONS = join(__dirname, '..', 'drizzle');

async function main() {
    const { config, logger } = start('migrate');
    const pool = new Pool({ connectionString: config.DATABASE_MIGRATE_URL, application_name: 'itrms-migrate' });
    try {
        await migrate(drizzle(pool), {
            migrationsFolder: MIGRATIONS,
            migrationsSchema: 'drizzle',
            migrationsTable: '__drizzle_migrations'
        });
        logger.info('migrations applied');
        const key = contextKeyOf(config.CONTEXT_HMAC_KEY);
        if (key) {
            const kid = contextKeyId(key);
            await pool.query(
                `INSERT INTO kernel.context_keys (kid, key) VALUES ($1, $2)
                 ON CONFLICT (kid) DO UPDATE SET retired_at = NULL`,
                [kid, key]
            );
            // a rotated-out key still verifies the requests already signed with it, for a few minutes
            await pool.query(
                `UPDATE kernel.context_keys SET retired_at = now() + interval '5 minutes'
                  WHERE kid <> $1 AND retired_at IS NULL`,
                [kid]
            );
            logger.info({ kid }, 'request-context key installed');
        } else {
            logger.warn('CONTEXT_HMAC_KEY is not set: the API cannot sign its request context');
        }
    } catch (error) {
        fail(logger, error);
    } finally {
        await pool.end();
    }
}

void main();
